"""Static compatibility data for models built on the TL protocol family.

Recovered statically from the app's bundled per-model configuration. It is a
**candidate** list, not a verified whitelist: the set of commands a given unit
answers is negotiated at runtime (see ``Session.negotiate_capabilities``), and
some payload semantics are not guaranteed across models. Treat ``tier`` as a
heuristic confidence level, not a promise. See ``docs/device-compatibility.md``.

Generated data -- do not edit by hand.
"""

from __future__ import annotations

from typing import NamedTuple


class DeviceSpec(NamedTuple):
    """Static signals recovered for one headset model."""

    name: str
    model_id: str          # "064C12"; "" when the model ships none
    uuid_type: str         # TYPE_DEFAULT | TYPE_SELF_PROTOCOL
    cmd_interval: int      # ms between commands
    noise_protocol: str    # PROTOCOL_STANDARD | PROTOCOL_FREE_STYLE
    pull_protocol: str     # PROTOCOL_STANDARD | PROTOCOL_FREE_STYLE
    device_type: str       # TYPE_TWS | TYPE_NECK
    feature_groups: tuple[str, ...]
    tier: str              # "A" | "B" | "C" (see docs)


