def _index_by_model() -> dict[str, tuple[DeviceSpec, ...]]:
    out: dict[str, list[DeviceSpec]] = {}
    for spec in KNOWN_DEVICES:
        if spec.model_id:
            out.setdefault(spec.model_id, []).append(spec)
    return {model: tuple(specs) for model, specs in out.items()}


#: model id -> the models that use it (model ids are not unique).
MODEL_IDS: dict[str, tuple[DeviceSpec, ...]] = _index_by_model()


def device_spec(model_id: str) -> DeviceSpec | None:
    """Return the first known model for ``model_id``, or ``None``."""
    specs = MODEL_IDS.get(model_id.upper())
    return specs[0] if specs else None


def devices_for_model(model_id: str) -> tuple[DeviceSpec, ...]:
    """Return every known model sharing ``model_id`` (may be empty)."""
    return MODEL_IDS.get(model_id.upper(), ())
